INSERT IGNORE INTO cltk_milniky (id, rok, rok_text, era, titulek, text, foto, foto_popisek, zdroj, jistota, visible, poradi) VALUES
(1, 1700, 'počátek 18. století', 'Ostrov před tenisem', 'Ostrov dostává jméno', 'Zápasy zvířat – štvanice – se přesunuly na ostrov Velké Benátky, pravděpodobně na počátku 18. století. Zakázány byly na počátku 19. století.', 'historie/hist-1800s-postl-svacina-na-stvanici.jpg', '', 'R23/1 s. 22, 24; https://www.praha7.cz/ostrov-stvanice/', 'podle klubu (rok zákazu v pramenech 1802/1805/1806/1816)', 1, 0),
(2, 1846, '1846–1849', 'Ostrov před tenisem', 'Negrelliho viadukt', 'Přes ostrov vyrostl železniční viadukt Severní státní dráhy (1846–1849, provoz od 1. 6. 1850). Jeho oblouky jsou dodnes kulisou kurtů.', '', '', 'https://cs.wikipedia.org/wiki/Negrelliho_viadukt', 'ověřeno', 1, 0),
(3, 1877, '2. polovina 19. století', 'Ostrov před tenisem', 'Velké Benátky baví Prahu', 'Amfiteátr Eugenia Averina, restaurace s tanečními sály, plovárna a dobové atrakce („33 divých žen, Amazonek krále Dahomejského“).', 'historie/hist-1800s-inzerat-velke-benatky-amazonky.jpg', '', 'R23/2 s. 44–47; cs.wikipedia Štvanice (ostrov)', 'podle klubu', 1, 0),
(4, 1893, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Založení klubu', 'Josef a Karel Cífkovi a Josef Rössler-Ořovský zakládají I. Český Lawn-Tennis Klub. První dvorce byly podle cs Wikipedie na Židovském ostrově, od 1894 na Střeleckém ostrově.', 'historie/hist-1893-josef-cifka-portret.jpg', '', 'Národní muzeum (inventář Rössler-Ořovský); cs.wikipedia I. ČLTK Praha; R13/2 s. 8', 'ověřeno (rok); místo NEOVĚŘENO', 1, 0),
(5, 1895, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Mistrovství zemí Koruny české', 'Hraje se první mistrovství zemí Koruny české; klub se stěhuje na bývalou závodní dráhu v Holešovicích-Bubnech (rok stěhování 1895 × 1896).', '', '', 'ceskytenis.info kap. 1; R13/2 s. 8', 'ověřeno (turnaj); stěhování podle klubu', 1, 0),
(6, 1901, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Domovem se stává Štvanice', 'Na ostrově vzniká pět kurtů, dřevěná klubovna a restaurace – „vše v krásné staré zahradě uprostřed Prahy“.', 'historie/hist-1900-skupinka-clenu-rossler-orovsky.jpg', '', 'https://umeleckepamatky.udu.cas.cz/objekt/311-tenisovy-dvorec-na-stvanici ; R13/2 s. 8–9', 'ověřeno', 1, 0),
(7, 1902, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Míčový turnaj I. Č. L. T. K.', 'Korespondenční lístek z 16. července 1902: dámy v dlouhých šatech a pánové ve slamácích na klubovém turnaji.', 'historie/hist-1902-pohlednice-micovy-turnaj.jpg', '', 'I.ČLTK Revue 02/2013 – 120 let (uploads/revue/pdf/revue-2013-2.pdf) s. 8', 'podle klubu', 1, 0),
(8, 1906, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Česká asociace a první medaile', 'Klub spoluzakládá Českou lawn-tennisovou asociaci. Bratři Žemlové berou bronz ve čtyřhře na olympijských mezihrách v Aténách (MOV je neuznává).', '', '', 'ceskytenis.info kap. 1; en.wikipedia Bohemia at the 1906 Intercalated Games', 'ověřeno', 1, 0),
(9, 1912, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Turnaj pod oblouky viaduktu', 'Turnaj na Štvanici přímo pod oblouky Negrelliho viaduktu. Ladislav Žemla je čtvrtý ve dvouhře na OH ve Stockholmu.', 'historie/hist-1912-turnaj-pod-negrelliho-viaduktem.jpg', '', 'I.ČLTK Revue 01/2023 + Bulletin 1893–2023 (uploads/revue/pdf/revue-2023-1.pdf) s. 39; en.wikipedia Tennis at the 1912 Summer Olympics', 'ověřeno', 1, 0),
(10, 1920, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Bronz z Antverp', 'Ladislav Žemla s Miladou Skrbkovou získává bronz v mixu na OH v Antverpách; téhož roku je prvním mistrem ČSR ve dvouhře.', 'historie/hist-1910s-ladislav-zemla.jpg', '', 'en.wikipedia Ladislav Žemla; Milada Skrbková', 'ověřeno', 1, 0),
(11, 1921, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'První Davisův pohár doma', 'První utkání Davisova poháru na čs. půdě: ČSR – Belgie 2:3 (13.–16. 6. 1921), za ČSR hráli Ardelt, Žemla a Just.', '', '', 'en.wikipedia 1921 International Lawn Tennis Challenge', 'ověřeno (utkání); místo Štvanice podle cs Wikipedie', 1, 0),
(12, 1927, '1926/1927', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Dřevěný centrkurt', 'Vyrůstá dřevěný centrální dvorec pro pět tisíc diváků, na kterém se hrálo až do roku 1983.', 'historie/hist-1926-skupina-hracu-a-cinovniku.jpg', '', 'ÚDU AV ČR (1926); ČTK 2006 (1927); R13/2 s. 9', 'rok 1926 × 1927 – rozpor; kapacita podle klubu', 1, 0),
(13, 1929, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Modřínová klubovna', 'Nová klubovna architekta Šuly, postavená Ringhofferovými závody, za tři čtvrtě milionu korun – s přispěním mecenášů.', 'historie/hist-1929-stara-klubovna.jpg', '', 'I.ČLTK Revue 02/2013 – 120 let (uploads/revue/pdf/revue-2013-2.pdf) s. 9–10', 'podle klubu (cs Wikipedie uvádí spíš 1930)', 1, 0),
(14, 1931, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Zimní stadion Štvanice', 'Na ostrově se 17. 1. 1931 hraje první zápas na první umělé ledové ploše v ČSR. Stadion hostil MS v hokeji 1933, 1938, 1947 a 1959; zbořen byl v roce 2011.', '', '', 'https://cs.wikipedia.org/wiki/Zimn%C3%AD_stadi%C3%B3n_%C5%A0tvanice', 'ověřeno', 1, 0),
(15, 1938, '1938–1948', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Klub za protektorátu', 'Předseda Ing. Jaromír Bečka drží klub bez vlivu Kuratoria a chrání tenisty včetně Drobného před totálním nasazením v Říši.', 'historie/hist-1940s-becka-predava-cenu-drobnemu.jpg', '', 'I.ČLTK Revue 02/2013 – 120 let (uploads/revue/pdf/revue-2013-2.pdf) s. 10, 15; I.ČLTK Revue 01/2023 + Bulletin 1893–2023 (uploads/revue/pdf/revue-2023-1.pdf) s. 42', 'podle klubu', 1, 0),
(16, 1947, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Mistr světa z tenisového klubu', 'Davis Cup ČSR – Francie 4:0 v Praze (14.–16. 6.). Na zimním stadionu na Štvanici vyhrává Československo MS v hokeji – v týmu Jaroslav Drobný.', '', '', 'en.wikipedia 1947 Davis Cup Europe Zone; https://www.praha7.cz/ostrov-stvanice/', 'ověřeno', 1, 0),
(17, 1948, '', 'I. Český Lawn-Tennis Klub (1893–1949)', 'Drobný vítězí v Paříži', 'Jaroslav Drobný vyhrává na Roland Garros čtyřhru i mix – jediné své grandslamové tituly z doby, kdy ještě hrál za klub. V Davis Cupu v Praze porazil Bergelina 6:0, 6:3, 7:5.', 'historie/hist-1940s-drobny-v-akci.jpg', '', 'en.wikipedia Jaroslav Drobný; 1948 Davis Cup Europe Zone', 'ověřeno', 1, 0),
(18, 1949, '', 'Motorlet (od 1949)', 'Emigrace a nové jméno', 'V červenci 1949 zůstává Drobný ve švýcarském Gstaadu. Klub je začleněn jako oddíl pod Sokol Jinonice a později TJ Motorlet.', 'historie/hist-1949-milan-drobny-becka-straubeova.jpg', '', 'I.ČLTK Revue 02/2013 – 120 let (uploads/revue/pdf/revue-2013-2.pdf) s. 11; cs.wikipedia Drobný', 'emigrace ověřena; názvy a roky klubu podle klubu', 1, 0),
(19, 1954, '', 'Motorlet (od 1949)', 'Drobný vítězem Wimbledonu', 'Ve finále porazil Kena Rosewalla 13-11, 4-6, 6-2, 9-7 – jako občan Egypta a jako jediný muž v brýlích v historii Wimbledonu.', 'historie/hist-1954-drobny-na-wimbledonske-trave.jpg', '', 'https://www.tennisfame.com/hall-of-famers/inductees/jaroslav-drobny ; en.wikipedia', 'ověřeno', 1, 0),
(20, 1962, '', 'Motorlet (od 1949)', 'Pužejová ve finále Wimbledonu', 'Věra Suková-Pužejová (mix RG 1957 s Javorským) jako první Čechoslovačka hraje finále Wimbledonu (Hantze Susmanová 4:6, 4:6).', 'historie/hist-1950s-vera-sukova-puzejova.jpg', '', 'en.wikipedia Věra Suková', 'ověřeno', 1, 0),
(21, 1966, '1963–1966', 'Motorlet (od 1949)', 'Mistři ligy s Kodešem', 'Spartak Praha Motorlet s mladým Janem Kodešem vyhrává ligu smíšených družstev (1966 doloženo, 1963–1965 pravděpodobně). Pod jménem Motorlet klub podle svých pramenů získal 12 titulů.', 'historie/hist-1966-mistri-ligy.jpg', '', 'cs.wikipedia Jan Kodeš; I.ČLTK Revue 02/2013 – 120 let (uploads/revue/pdf/revue-2013-2.pdf) s. 11', 'podle klubu (foto „Mistr ligy 1966“, R13/2 s. 11) a cs Wikipedie; nezávisle NEOVĚŘENO – roky 12 titulů Motorletu nikde nezávisle vypsané nejsou', 1, 0),
(22, 1971, '1971–1972', 'TJ Dopravní podnik (kolem 1970–1990)', 'Daviscupové bitvy na starém centru', 'ČSSR – Španělsko 3:2 (16.–18. 7. 1971): Kodeš porazil Orantese i Gisberta, Pála Gisberta 6:0, 6:1, 6:1. V květnu 1972 Kodeš na Štvanici porazil mladého Björna Borga 6:2, 6:3, 7:5.', 'historie/hist-1971-kodes-a-pala-oslava-davis-cup.jpg', '', 'en.wikipedia 1971 a 1972 Davis Cup Europe Zone; ceskytenis.info kap. 6', 'ověřeno', 1, 0),
(23, 1973, '', 'TJ Dopravní podnik (kolem 1970–1990)', 'Kodeš vítězem Wimbledonu', 'Štvanický odchovanec, tehdy hráč Sparty, vyhrává Wimbledon (Metreveli 6-1, 9-8, 6-3); trénuje ho štvanický Pavel Korda.', 'historie/hist-1970s-jan-kodes-na-stvanici.jpg', '', 'https://www.tennisfame.com/hall-of-famers/inductees/jan-kodes ; cs.wikipedia Tenisový klub Sparta Praha', 'ověřeno', 1, 0),
(24, 1975, '', 'TJ Dopravní podnik (kolem 1970–1990)', 'Titul a slavné semifinále', 'Klub (TJ Dopravní podnik) vyhrává ligu. V semifinále Davis Cupu s Austrálií na Štvanici (26.–28. 9.) otáčí Jiří Hřebec zápas s Rochem 3:6, 4:6, 6:1, 6:3, 6:3.', 'historie/hist-1975-vitezny-prvoligovy-tym.jpg', '', 'en.wikipedia 1975 Davis Cup; iROZHLAS 2018 (titul)', 'ověřeno', 1, 0),
(25, 1979, '', 'TJ Dopravní podnik (kolem 1970–1990)', 'Tendiv a Švédové', 'Vzniká Tendiv – štvanické tenisové divadlo („Štvanice byla ostrovem svobody“). Na starém centru se hraje Davis Cup ČSSR – Švédsko 3:2 (14.–16. 9. 1979).', 'historie/hist-1978-stary-centrkurt-davis-cup-svedsko.jpg', 'Davis Cup ČSSR – Švédsko na starém centrkurtu, 1979', 'R13/1 s. 17 (Tendiv); en.wikipedia 1979 Davis Cup Europe Zone', 'Tendiv podle klubu; utkání ověřeno', 1, 0),
(26, 1980, '', 'TJ Dopravní podnik (kolem 1970–1990)', 'Davisův pohár', 'Československo vyhrává Davis Cup (finále s Itálií 4:1 ve Sportovní hale). Kodeš a Složil hráli v Evropské zóně, trenérem týmu byl štvanický Pavel Korda.', 'historie/hist-1980-musketyri-davis-cupu-po-letech.jpg', '', 'en.wikipedia 1980 Davis Cup; iROZHLAS/ČTK 5. 5. 2019', 'ověřeno', 1, 0),
(27, 1983, '', 'TJ Dopravní podnik (kolem 1970–1990)', 'Konec staré Štvanice', 'Se stavbou metra pod Vltavou začíná demolice starého areálu – dřevěné klubovny i původního centrkurtu.', 'historie/hist-1983-stary-centrkurt-pred-demolici.jpg', '', 'ČTK 14. 6. 2006 (archiweb)', 'ověřeno', 1, 0),
(28, 1986, '', 'TJ Dopravní podnik (kolem 1970–1990)', 'Nový Štvanický stadion', '16. 6. 1986 se otevírá nejmodernější tenisový areál tehdejšího Československa (arch. Kales a Novotná). Premiérou je Pohár federace (20.–27. 7.): Martina Navrátilová se poprvé po emigraci vrací a ve finále porazí Mandlíkovou 7:5, 6:1.', 'historie/hist-1986-novy-centralni-dvorec.jpg', '', 'ČTK 14. 6. 2006; ÚDU AV ČR; en.wikipedia 1986 Federation Cup', 'ověřeno', 1, 0),
(29, 1990, '', 'I. ČLTK Praha (1990–dnes)', 'Návrat jména a titulu', 'Klub se vrací k názvu I. ČLTK Praha a vyhrává mistrovství ČSFR družstev (Kodeš ml., Hovorka, Rikl, D. Vacek, A. a J. Strnadovy, Lásková).', '', '', 'iROZHLAS 20. 12. 2018; I.ČLTK Revue 01/2023 + Bulletin 1893–2023 (uploads/revue/pdf/revue-2023-1.pdf) s. 3, 12', 'titul ověřen; rok změny názvu podle klubu', 1, 0),
(30, 2002, '', 'I. ČLTK Praha (1990–dnes)', 'Povodeň', 'Celý areál je pod vodou, v hale přes čtyři metry vody, škody 100–120 milionů korun. Pojistka, kterou svaz uzavřel pět let předtím, umožnila obnovu; areál se znovu otevřel koncem května 2003.', 'historie/hist-2002-povoden-zaplaveny-areal.jpg', '', 'ČTK 14. 6. 2006; Deník/ČTK 2016; kompilace tisku FA ČVUT 2011', 'ověřeno', 1, 0),
(31, 2010, '', 'I. ČLTK Praha (1990–dnes)', 'Plíškovy vládnou juniorkám', 'Karolína Plíšková vyhrává juniorku Australian Open, Kristýna juniorku Wimbledonu – obě jako hráčky I. ČLTK.', 'historie/hist-2010-sestry-pliskovy-juniorske-tituly.jpg', '', 'https://www.cztenis.cz/hrac/31168 ; /31169', 'ověřeno', 1, 0),
(32, 2011, '2011–2012', 'I. ČLTK Praha (1990–dnes)', 'Lucie Hradecká a Fed Cup', 'Hradecká vyhrává s Hlaváčkovou Roland Garros a rozhodující čtyřhrou finále Fed Cup; Benešová vyhrává mix ve Wimbledonu. V roce 2012 Hradecká přiváží olympijské stříbro, Ivo Minář vyhrává Davis Cup a ve foyer je 14. 6. 2012 odhalena deska Jaroslava Drobného.', 'historie/hist-2011-hradecka-pohar-roland-garros.jpg', '', 'en.wikipedia Lucie Hradecká, 2011 Fed Cup, Ivo Minář; cs.wikipedia Drobný', 'ověřeno', 1, 0),
(33, 2018, '', 'I. ČLTK Praha (1990–dnes)', 'Titul po 28 letech', '10. 6. 2018 slaví klub 125 let. V prosinci vyhrává extraligu – finále v Říčanech s Prostějovem 5:4.', 'historie/hist-2018-extraliga-pohary.jpg', '', 'iROZHLAS 20. 12. 2018; tenisovaextraliga.cz; I. ČLTK Praha, stránka „Oslavy 125 let klubu“', 'ověřeno', 1, 0),
(34, 2019, '', 'I. ČLTK Praha (1990–dnes)', 'Obhajoba', 'Extraliga obhájena – finále 18. 12. 2019 s Přerovem 5:2 (Krstev, Šátral, Šafránek, Staněk, Kližan, Martincová, Vondroušová, Muchová, Detiuc, Forejtek).', 'historie/hist-2019-extraliga-vitezny-tym.jpg', '', 'Sport.cz/ČTK 18. 12. 2019; tenisovaextraliga.cz', 'ověřeno', 1, 0),
(35, 2021, '', 'I. ČLTK Praha (1990–dnes)', 'Stříbro z Tokia', 'Markéta Vondroušová získává na OH Tokio 2020 stříbro ve dvouhře (finále s Bencicovou 5:7, 6:2, 3:6).', 'historie/hist-2021-vondrousova-tokio-stribro.jpg', '', 'en.wikipedia Markéta Vondroušová', 'ověřeno', 1, 0),
(36, 2022, '', 'I. ČLTK Praha (1990–dnes)', 'Reprezentace na klubové antuce', 'Kvalifikace BJK Cupu ČR – Velká Británie 3:2 na antuce I. ČLTK (15.–16. 4.): Vondroušová porazila Raducanuovou 6:1, 6:1 a s Muchovou vyhrála rozhodující čtyřhru. V červenci se prezidentem klubu stává Ing. Petr Šimůnek.', '', '', 'en.wikipedia 2022 Billie Jean King Cup qualifying round; I. ČLTK Praha, článek „Ing. Petr Šimůnek byl zvolen novým prezidentem klubu“ (2022)', 'ověřeno', 1, 0),
(37, 2023, '', 'I. ČLTK Praha (1990–dnes)', '130 let a třetí wimbledonský titul', 'Markéta Vondroušová vyhrává Wimbledon jako první nenasazená hráčka historie. 22. 7. 2023 slaví klub 130 let (asi 200 členů na společné fotografii na tribuně centrkurtu). 28. 7. se otevírá lávka HolKa.', 'historie/vyroci-130-let-spolecna-fotografie.jpg', '', 'en.wikipedia Vondroušová; I. ČLTK Praha, stránka „Oslavy 130 let klubu 22. 7. 2023“; ČT24 28. 7. 2023', 'ověřeno', 1, 0),
(38, 2026, '', 'I. ČLTK Praha (1990–dnes)', 'Rok Karolíny Muchové', 'Muchová vyhrává WTA 1000 v Dauhá a WTA 500 v Bad Homburgu, 11. 7. hraje finále Wimbledonu a v srpnu vyhrává s Jakubem Menšíkem mix na US Open. Nový stadion stojí 40 let; podle newsletteru 3/2026 se na Štvanici otevírá Síň slávy českého tenisu.', 'historie/karolina-muchova-ve-finale-wimbledonu.jpg', '', 'usopen.org; olympics.com; I. ČLTK Praha, článek „Karolína Muchová ovládla smíšenou čtyřhru na US Open“ (2026); newsletter 3/2026', 'ověřeno (Síň slávy podle klubu)', 1, 0);
