(36, 2008, 2, '02/2008', 'revue/revue-2008-2.jpg', 'maminky s miminky na kurtu („Nejmladší naděje klubu“)', '[\"Nejmladší naděje klubu aneb rodičovské štěstí na Štvanici\",\"Prezidentem I. ČLTK znovu zvolen František Stejskal\",\"Jiří Hřebec: Nejvíc mě baví Barborka\"]', '[[\"03\",\"Interview/Jiří Hřebec\"],[\"08\",\"Prezidentem I. ČLTK znovu zvolen František Stejskal\"],[\"09\",\"Stalo se\"],[\"10\",\"ECM Prague Open: Hernychův hattrick!\"],[\"13\",\"Šátral má titul z Pardubic\"],[\"14\",\"Starší žáci finále M ČR družstev prohráli\"],[\"18\",\"Co nového u.../Iveta Benešová\"],[\"20\",\"Z klubu/Nejmladší štvanická krev\"],[\"24\",\"Partneři klubu/Auto Kout Centrum - Miroslav Kout\"],[\"26\",\"Luboš Štych/Kladeňák, kterého brusle minuly\"],[\"30\",\"V.I.P. turnaj/Mirek Topolánek prohrál až ve finále\"],[\"32\",\"CTC/Na kole v Haagu\"],[\"34\",\"Rozhovor/Lucie Kvasnicová alias DJ Lucca\"],[\"38\",\"Pánská jízda na vodě\"],[\"40\",\"Ve vzpomínkách/Julius Drobný\"]]', 44, '500 výtisků', '', '', 'revue/pdf/revue-2008-2.pdf', '16,0', 1, 35),
(37, 2008, 1, '01/2008', 'revue/revue-2008-1.jpg', 'Pavel Huťka s lahví klubového vína', '[\"Pavel Huťka: Tohle víno jsme chtěli\",\"Prezident I. ČLTK František Stejskal slavil „60”\",\"Milan Šrejber: První den na Štvanici jsem strávil u karet\",\"Čtyřutkání CTC: Italové rozdávali kanáry\"]', '[[\"03\",\"Interview/Milan Šrejber\"],[\"08\",\"Stalo se\"],[\"12\",\"I. ČLTK má svoje víno\"],[\"14\",\"Ze společnosti/Prezident klubu slavil „60”\"],[\"16\",\"Čtyřutkání CTC/Italové rozdávali kanáry\"],[\"20\",\"Závodní tenis/To byla sezona!\"],[\"22\",\"Co nového u.../Martin Damm\"],[\"24\",\"Partneři klubu/Ferona - Miroslav Horák\"],[\"26\",\"Rozhovor/Vlasta Vopičková\"],[\"30\",\"Mistry I. ČLTK v golfu Münster a Riklová\"],[\"34\",\"Hrají na Štvanici/Jiří Hrdina\"],[\"36\",\"Vánoční večírek rozproudil DJ Lucaso\"],[\"38\",\"Na slovíčko/Luboš Zahradník\"],[\"40\",\"Ve vzpomínkách.../Manželé Součkovi\"]]', 44, '500 výtisků', '', '', 'revue/pdf/revue-2008-1.pdf', '16,3', 1, 36),
(38, 2007, 2, '02/2007', 'revue/revue-2007-2.jpg', 'Michaella Krajicek na ECM Prague Open 2007', '[\"ECM Prague Open: Totální nasazení\",\"Interview: Vladislav Šavrda\",\"Pardubice patřily dorostencům I. ČLTK\",\"V.I.P. turnaj vyhrál Václav Klaus\",\"DJ Lucaso: Ďábel v podkolenkách\"]', '[[\"03\",\"ECM Prague Open: Totální nasazení\"],[\"06\",\"Stalo se\"],[\"08\",\"Jan Kodeš: Kurt už se mi zdá nějak větší\"],[\"10\",\"Interview/Vladislav Šavrda\"],[\"14\",\"Závodní tenis/Pardubice patřily dorostencům I. ČLTK\"],[\"18\",\"Co nového u.../Jan Mertl\"],[\"20\",\"Safina Cup vyhrála Zarina Diyas\"],[\"22\",\"Partneři klubu/Třinecké železárny - Evžen Balko\"],[\"24\",\"Rozhovor/Iva Šimůnková\"],[\"28\",\"CTC/Návštěva v Dublinu: Fitzwilliam udělal dojem\"],[\"30\",\"Ve V.I.P. turnaji triumfoval Václav Klaus\"],[\"34\",\"Rekreační turnaje dostanou nový kabát\"],[\"35\",\"Děti si užily tři turnaje\"],[\"36\",\"Hrají na Štvanici/DJ Lucaso: Ďábel v podkolenkách\"],[\"38\",\"Z archivu/»Nejmladší« ligový titul\"],[\"40\",\"Na slovíčko/Martin Zenkl\"]]', 44, '500 výtisků', '', '', 'revue/pdf/revue-2007-2.pdf', '16,8', 1, 37),
