(40, 2006, 2, '02/2006', 'revue/revue-2006-2.jpg', 'Martina Navrátilová při ECM Prague Open 2006', '[\"ECM Prague Open: Na Martinu se stála fronta\",\"Interview: Jaromír Bečka\",\"V.I.P. turnaj: Milé červencové poděkování\",\"Centenary Tennis Clubs: Byli jsme v Bordeaux aneb návštěva v sedmém nebi\",\"Štvanické bitvy: Kodešův »zázrak«\"]', '[[\"03\",\"Na Martinu se stála fronta\"],[\"06\",\"ECM Prague Open 2006: Kolotoč, ale i zážitek\"],[\"10\",\"Stalo se\"],[\"14\",\"Jaromír Bečka: Zbyly jen platany...\"],[\"20\",\"Jan Hernych: Auto zase odložil\"],[\"22\",\"Závodní tenis/Největší úspěchy hráčů I. ČLTK\"],[\"24\",\"Petr Šimůnek: Ještě se naučit golf...\"],[\"27\",\"Stalo se/Milé červencové poděkování\"],[\"30\",\"Partneři klubu/Agrofert - rozhovor s J. Kadaníkem\"],[\"32\",\"Štvanická školička/Jana Cup\"],[\"34\",\"Bordeaux: Návštěva v sedmém nebi\"],[\"36\",\"Hrají na Štvanici/Michal Horáček\"],[\"38\",\"Štvanické bitvy/Kodešův »zázrak«\"],[\"40\",\"Na slovíčko/Pavel Mudřík\"]]', 44, '500 výtisků', '', '', 'revue/pdf/revue-2006-2.pdf', '20,1', 1, 39);
