(1, 'info', 'Pro koho', NULL, NULL, '', '', '', '', '', '', '', 'Pro děti od 3 do 9 let, zejména na výkonnostní úrovni. Talentované děti postupně užším výběrem reprezentují klub v soutěžích družstev i jednotlivců. Nábory jsou vždy na jaře a na podzim.', '', 1, 0, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(2, 'info', 'Co děláme', NULL, NULL, '', '', '', '', '', '', '', 'Pravidelná výuka, turnaje dětí v minitenise, na středním kurtu a v babytenise, mistrovská utkání družstev, kempy a soustředění.', '', 1, 1, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(3, 'info', 'Platba', NULL, NULL, '', '', '', '', '', '', '', 'Cena zahrnuje trenéra i pronájem kurtu. Platí se kurzovné za celé období, nebo podle skutečnosti – podle trenéra. Vyúčtování přichází koncem měsíce e-mailem. Základní členství Tenisové školy 1 000 Kč se hradí vždy na začátku roku.', '', 1, 2, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(4, 'info', 'Počasí a náhrady', NULL, NULL, '', '', '', '', '', '', '', 'Při nepříznivém počasí se trénuje v hale; když je hala obsazená, trénink se ruší a neúčtuje. Náhrady jen po dohodě a ve volných kapacitách.', '', 1, 3, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(5, 'info', 'Rodiče', NULL, NULL, '', '', '', '', '', '', '', 'Během tréninků se prosím zdržujte mimo dvorec.', '', 1, 4, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(6, 'harmonogram', 'Tréninky v provizorním režimu (testování zimních rozvrhů)', '2026-09-07', NULL, '', '', '', '', '', '', '', '', '', 1, 0, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(7, 'harmonogram', 'Schůzka s rodiči – sraz na recepci od 18:30', '2026-09-07', NULL, '', '', '', '', '', '', '', '', '', 1, 1, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(8, 'harmonogram', 'Nehraje se – stavba hal', '2026-09-21', '2026-09-28', '', '', '', '', '', '', '', '', '', 1, 2, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
(9, 'harmonogram', 'Tréninky podle zimních rozvrhů', '2026-09-29', '2027-04-02', '', '', '', '', '', '', '', '', '', 1, 3, '2026-10-04 12:38:32', '2026-10-04 12:38:32'),
