(2, '2026-08-27', 'New York', 'US Open · finále · smíšená čtyřhra', 'Karolína Muchová a Jakub Menšík', 'Belinda Bencicová, Flavio Cobolli', 'Česká dvojice získala senzační grandslamový titul, když ve finále porazila švýcarsko-italský pár Bencicová, Cobolli.', '[\"6:3\",\"1:6\",\"10:6\"]', 'Titul', '', '', 1, 1, '2026-10-04 12:38:30', '2026-10-04 12:38:30'),
