(4, '2026-07-11', 'Londýn', 'Wimbledon · finále · dvouhra žen', 'Karolína Muchová', 'Linda Nosková', 'První ryze české finále ženské dvouhry ve Wimbledonu. Dva dny nato kariérní maximum – 6. místo žebříčku WTA.', '[\"2:6\",\"7:5\",\"3:6\"]', 'Finále', '', '', 1, 3, '2026-10-04 12:38:30', '2026-10-04 12:38:30'),
(5, '2026-06-27', 'Bad Homburg', 'WTA 500 Bad Homburg · finále · tráva', 'Karolína Muchová', 'Naomi Osaka', 'Ve finále vedla 6:1, 1:0, když Naomi Osaka skrečovala. Premiérový titul na trávě a návrat do elitní desítky.', '[\"6:1\",\"1:0 skr.\"]', 'Titul', '', '', 1, 4, '2026-10-04 12:38:30', '2026-10-04 12:38:30'),
(6, '2026-06-21', 'Figueira da Foz', 'WTA 125 Figueira da Foz · finále', 'Darja Viďmanová', 'Ayla Aksuová', 'Ve finále porazila Turkyni Aylu Aksuovou. První titul z okruhu WTA.', '[\"6:2\",\"6:3\"]', 'Titul', '', '', 1, 5, '2026-10-04 12:38:30', '2026-10-04 12:38:30'),
(7, '2026-02-15', 'Praha', 'ITF W75 Conseq Prague Open · finále · Štvanice', 'Tereza Martincová', 'Sinja Krausová', 'Doma na Štvanici prošla z kvalifikace až k titulu, ve finále porazila nejvýše nasazenou Sinju Krausovou.', '[\"6:3\",\"6:4\"]', 'Titul', '', '', 1, 6, '2026-10-04 12:38:30', '2026-10-04 12:38:30'),
(8, '2026-02-14', 'Dauhá', 'WTA 1000 Dauhá · finále', 'Karolína Muchová', 'Victoria Mboko', 'Ve finále porazila Kanaďanku Victorii Mboko a získala dosud největší titul kariéry.', '[\"6:4\",\"7:5\"]', 'Titul', '', '', 1, 7, '2026-10-04 12:38:30', '2026-10-04 12:38:30');
